def transform(grid):
    from collections import deque, Counter
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); selected=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=bg or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); comp=set(); edge=False
        while q:
          y,x=q.popleft(); comp.add((y,x)); edge |= y in (0,h-1) or x in (0,w-1)
          for yy,xx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
            if 0<=yy<h and 0<=xx<w and grid[yy][xx]==bg and (yy,xx) not in seen:
              seen.add((yy,xx)); q.append((yy,xx))
        if edge: continue
        miny=min(y for y,x in comp); maxy=max(y for y,x in comp)
        minx=min(x for y,x in comp); maxx=max(x for y,x in comp)
        best=[]
        for y0 in range(miny,maxy+1):
          for y1 in range(y0,maxy+1):
            for x0 in range(minx,maxx+1):
              for x1 in range(x0+1,maxx+1):
                rect=[(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1)]
                if len(rect)>len(best) and all(p in comp for p in rect): best=rect
        selected.extend(best)
    out=[row[:] for row in grid]
    for r,c in selected: out[r][c]=4
    return out
